/* Quiet theme: calm, exact surfaces for apps and dashboards.
   Flat white on an off-white page, hairline edges instead of shadows, one
   colour used only where it means something, compact controls, and light
   numbers that lead. The main button is a small pressable key.
   Load after the component styles, then put data-glass-theme="quiet" on
   <html> or any wrapper. Glass and bubble finishes keep their own look. */
[data-glass-theme="quiet"] {
  --glass-tint: #18181b;
  --glass-on-tint: #ffffff;
  --glass-fg: #0b0b0d;
  --glass-shadow: 24 24 27;
  --glass-focus: #2563eb;
  --q-canvas: #f7f7f8;
  --q-surface: #ffffff;
  --q-line: rgb(24 24 27 / 0.08);
  --q-line-strong: rgb(24 24 27 / 0.13);
  --q-sunk: rgb(24 24 27 / 0.04);
  --q-muted: rgb(24 24 27 / 0.56);
  --q-lift: 0 1px 2px rgb(24 24 27 / 0.05);
  --q-float: 0 0 0 1px rgb(24 24 27 / 0.07), 0 4px 8px -2px rgb(24 24 27 / 0.06), 0 18px 40px -12px rgb(24 24 27 / 0.18);
}

/* ---------- Buttons: compact keys ---------- */
[data-glass-theme="quiet"] .gb.gb.gb.gb[data-effect="flat"] {
  --gb-h: 36px;
  --gb-px: 14px;
  --gb-fs: 14px;
  --gb-inset: inset 0 0 0 0 transparent;
  --gb-rim-hi: transparent;
  --gb-rim-lo: transparent;
  --gb-lift: 0px;
  --gb-drop: transparent;
  --gb-light: 0;
  --gb-backdrop: none;
  animation: none;
  transition: background-color 0.15s, box-shadow 0.15s, filter 0.15s, scale 0.5s cubic-bezier(0.3, 1.5, 0.5, 1);
}
[data-glass-theme="quiet"] .gb.gb.gb.gb[data-effect="flat"][data-size="sm"] { --gb-h: 30px; --gb-px: 11px; --gb-fs: 13px; }
[data-glass-theme="quiet"] .gb.gb.gb.gb[data-effect="flat"][data-size="lg"] { --gb-h: 44px; --gb-px: 20px; --gb-fs: 15px; }
[data-glass-theme="quiet"] .gb.gb.gb.gb[data-effect="flat"]::before,
[data-glass-theme="quiet"] .gb.gb.gb.gb[data-effect="flat"]::after { opacity: 0; }

/* Main: a small key with a lit top edge and a soft drop */
[data-glass-theme="quiet"] .gb.gb.gb.gb[data-effect="flat"][data-variant="primary"] {
  --gb-fg: var(--glass-on-tint);
  background: linear-gradient(180deg, color-mix(in srgb, var(--glass-tint) 86%, #fff), var(--glass-tint) 55%);
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / 0.16),
    inset 0 -1px 0 rgb(0 0 0 / 0.12),
    0 0 0 1px color-mix(in srgb, var(--glass-tint) 78%, #000),
    0 1px 2px rgb(24 24 27 / 0.18),
    0 4px 10px -4px color-mix(in srgb, var(--glass-tint) 55%, transparent);
}
[data-glass-theme="quiet"] .gb.gb.gb.gb[data-effect="flat"][data-variant="primary"]:hover:not(:disabled) { filter: brightness(1.1); }
[data-glass-theme="quiet"] .gb.gb.gb.gb[data-effect="flat"][data-variant="primary"]:active:not(:disabled) {
  filter: none;
  background: var(--glass-tint);
  box-shadow: inset 0 1px 3px rgb(0 0 0 / 0.3), 0 0 0 1px color-mix(in srgb, var(--glass-tint) 78%, #000);
}
/* Secondary: white with a hairline */
[data-glass-theme="quiet"] .gb.gb.gb.gb[data-effect="flat"][data-variant="secondary"] {
  --gb-fg: var(--glass-fg);
  background: var(--q-surface);
  box-shadow: 0 0 0 1px var(--q-line-strong), var(--q-lift);
}
[data-glass-theme="quiet"] .gb.gb.gb.gb[data-effect="flat"][data-variant="secondary"]:hover:not(:disabled) { background: #fafafa; }
[data-glass-theme="quiet"] .gb.gb.gb.gb[data-effect="flat"][data-variant="secondary"]:active:not(:disabled) { background: #f2f2f3; box-shadow: 0 0 0 1px var(--q-line-strong), inset 0 1px 2px rgb(24 24 27 / 0.08); }
/* Ghost: text until hovered */
[data-glass-theme="quiet"] .gb.gb.gb.gb[data-effect="flat"][data-variant="ghost"] {
  --gb-fg: var(--q-muted);
  background: transparent;
  box-shadow: none;
}
[data-glass-theme="quiet"] .gb.gb.gb.gb[data-effect="flat"][data-variant="ghost"]:hover:not(:disabled) { --gb-fg: var(--glass-fg); background: var(--q-sunk); }

/* ---------- Fields ---------- */
[data-glass-theme="quiet"] .gf:not([data-effect="glass"], [data-effect="bubble"]) {
  --gf-h: 36px;
  --gf-fill: var(--q-surface);
  --gf-ring: var(--q-line-strong);
  --gf-inset: 0 1px 2px rgb(24 24 27 / 0.04);
  --gf-rim-hi: transparent;
  --gf-rim-lo: transparent;
  font-size: 14px;
}
[data-glass-theme="quiet"] .gf:not([data-effect="glass"], [data-effect="bubble"]):hover { --gf-ring: rgb(24 24 27 / 0.2); }
[data-glass-theme="quiet"] .gf:focus-within,
[data-glass-theme="quiet"] .gf[data-open] { --gf-ring: var(--glass-focus); --gf-halo: color-mix(in srgb, var(--glass-focus) 14%, transparent); }
[data-glass-theme="quiet"] .gfield label, [data-glass-theme="quiet"] .gf-label { font-size: 13px; font-weight: 500; }

/* ---------- Cards: hairline, no shadow ---------- */
[data-glass-theme="quiet"] .gc[data-effect="flat"],
[data-glass-theme="quiet"] .gc:not([data-effect]) {
  --gc-fill: var(--q-surface);
  --gc-ring: var(--q-line);
  --gc-drop: 0 1px 2px rgb(24 24 27 / 0.03);
  --gc-radius: min(var(--glass-radius), 16px);
  --gc-rim-hi: transparent;
  --gc-rim-lo: transparent;
  padding: 20px;
}
[data-glass-theme="quiet"] .gc[data-effect="flat"][data-level="2"] { --gc-fill: #fafafa; --gc-radius: min(var(--glass-radius), 12px); padding: 16px; }
[data-glass-theme="quiet"] .gc[data-effect="flat"][data-active] {
  background: var(--q-surface);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--glass-tint) 55%, transparent), 0 0 0 4px color-mix(in srgb, var(--glass-tint) 7%, transparent), 0 8px 20px -14px color-mix(in srgb, var(--glass-tint) 60%, transparent);
}
[data-glass-theme="quiet"] .gc-title { font-size: 15px; font-weight: 500; letter-spacing: -0.01em; }

/* ---------- Menus and popovers ---------- */
[data-glass-theme="quiet"] .gp:not([data-effect="glass"], [data-effect="bubble"]) { border-radius: 12px; box-shadow: var(--q-float); }
[data-glass-theme="quiet"] .gp:not([data-effect="glass"], [data-effect="bubble"]) .gp-hl { background: rgb(24 24 27 / 0.055); box-shadow: none; }
[data-glass-theme="quiet"] .gp-item { font-size: 14px; }

/* ---------- Tables: a grey header band and hairline rows ---------- */
[data-glass-theme="quiet"] .gtb { padding: 6px; border-radius: min(var(--glass-radius), 16px); box-shadow: 0 0 0 1px var(--q-line), 0 1px 2px rgb(24 24 27 / 0.03); }
[data-glass-theme="quiet"] .gtb th { padding: 9px 14px; font-size: 13px; font-weight: 400; color: var(--q-muted); background: rgb(24 24 27 / 0.035); border-bottom: 0; }
[data-glass-theme="quiet"] .gtb th:first-child { border-radius: 10px 0 0 10px; }
[data-glass-theme="quiet"] .gtb th:last-child { border-radius: 0 10px 10px 0; }
[data-glass-theme="quiet"] .gtb td { padding: 13px 14px; border-bottom-color: rgb(24 24 27 / 0.055); }
[data-glass-theme="quiet"] .gtb tbody tr:hover { background: rgb(24 24 27 / 0.02); }

/* ---------- Badges: soft tint with a matching hairline ---------- */
[data-glass-theme="quiet"] .gbd:not([data-effect="glass"], [data-effect="bubble"]) { height: 22px; padding: 0 8px; font-weight: 500; box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--gbd-c) 16%, transparent); }
[data-glass-theme="quiet"] .gbd[data-tone="accent"] { --gbd-c: #1d4ed8; --gbd-bg: #eef4ff; }
[data-glass-theme="quiet"] .gbd[data-tone="success"] { --gbd-c: #15803d; --gbd-bg: #effbf3; }
[data-glass-theme="quiet"] .gbd[data-tone="warning"] { --gbd-c: #a16207; --gbd-bg: #fefaec; }
[data-glass-theme="quiet"] .gbd[data-tone="danger"] { --gbd-c: #c2262d; --gbd-bg: #fef1f1; }

/* ---------- Tabs: a sunk track with a white chip ---------- */
[data-glass-theme="quiet"] .gtabs:not([data-variant="subtle"]):not([data-effect="glass"], [data-effect="bubble"]) { background: rgb(24 24 27 / 0.05); box-shadow: inset 0 0 0 1px rgb(24 24 27 / 0.04); }
[data-glass-theme="quiet"] .gtabs:not([data-effect="glass"], [data-effect="bubble"]) .gtabs-pill { background: #fff; box-shadow: 0 0 0 1px rgb(24 24 27 / 0.08), 0 1px 2px rgb(24 24 27 / 0.08); }
[data-glass-theme="quiet"] .gtab { font-size: 13.5px; padding: 5px 12px; }

/* ---------- Controls ---------- */
[data-glass-theme="quiet"] .gsw-track { box-shadow: inset 0 0 0 1px rgb(24 24 27 / 0.06); }
[data-glass-theme="quiet"] .gsw-thumb, [data-glass-theme="quiet"] .gsl-thumb { box-shadow: 0 0 0 1px rgb(24 24 27 / 0.1), 0 1px 3px rgb(24 24 27 / 0.16); }

[data-glass-theme="quiet"] .gck { box-shadow: inset 0 0 0 1px var(--q-line-strong), 0 1px 1px rgb(24 24 27 / 0.04); }

/* ---------- Progress ---------- */
[data-glass-theme="quiet"] .gpr-track { --gpr-track: rgb(24 24 27 / 0.06); box-shadow: none; }

/* ---------- Dialog and tooltip ---------- */
[data-glass-theme="quiet"] .gdl { border-radius: 18px; box-shadow: 0 0 0 1px var(--q-line), 0 30px 70px -24px rgb(24 24 27 / 0.35); }
[data-glass-theme="quiet"] .gtt-tip:not([data-effect="glass"], [data-effect="bubble"]) { color: #fafafa; background: #18181b; box-shadow: 0 4px 12px -4px rgb(0 0 0 / 0.3); }

/* ---------- App parts ---------- */
/* Sidebar: no panel; quiet rows; the current page is a small white card */
[data-glass-theme="quiet"] .gsb.gc[data-effect="flat"] { background: transparent; box-shadow: none; padding: 8px 4px; }
[data-glass-theme="quiet"] .gsb.gc[data-effect="flat"]::after { display: none; }
[data-glass-theme="quiet"] .gsb-label { padding: 0 10px 6px; font-size: 11px; font-weight: 500; letter-spacing: 0.1em; color: rgb(24 24 27 / 0.45); }
[data-glass-theme="quiet"] .gsb-item { min-height: 34px; color: rgb(24 24 27 / 0.66); }
[data-glass-theme="quiet"] .gsb-item:hover { background: rgb(24 24 27 / 0.04); }
[data-glass-theme="quiet"] .gsb[data-effect="flat"] .gsb-item[aria-current="page"] { font-weight: 500; color: var(--glass-fg); background: #fff; box-shadow: 0 0 0 1px var(--q-line), 0 1px 2px rgb(24 24 27 / 0.05); }
[data-glass-theme="quiet"] .gsb[data-effect="flat"] .gsb-item[aria-current="page"]::before { display: none; }
[data-glass-theme="quiet"] .gsb-count { font-weight: 500; color: rgb(24 24 27 / 0.6); background: #fff; box-shadow: 0 0 0 1px var(--q-line); }
/* Numbers lead: large, light, aligned */
[data-glass-theme="quiet"] .gst-value { font-size: 30px; font-weight: 400; letter-spacing: -0.035em; }
[data-glass-theme="quiet"] .gst-label { font-size: 13px; color: var(--q-muted); }
[data-glass-theme="quiet"] .gch, [data-glass-theme="quiet"] .gdn { --gch-1: #a1a1aa; --gch-2: #d4d4d8; --gch-3: #52525b; }
[data-glass-theme="quiet"] .gdt-bar .gf { --gf-h: 34px; }
[data-glass-theme="quiet"] .gpg-btn[aria-current="page"] { color: var(--glass-fg); background: #fff; box-shadow: 0 0 0 1px var(--q-line-strong), var(--q-lift); }

/* ---------- Dark ---------- */
[data-glass-mode="dark"] [data-glass-theme="quiet"],
[data-glass-mode="dark"][data-glass-theme="quiet"] {
  --glass-fg: #f4f4f5;
  --glass-shadow: 244 244 245;
  --glass-focus: #60a5fa;
  --q-canvas: #0c0c0e;
  --q-surface: #151517;
  --q-line: rgb(255 255 255 / 0.07);
  --q-line-strong: rgb(255 255 255 / 0.11);
  --q-sunk: rgb(255 255 255 / 0.05);
  --q-muted: rgb(244 244 245 / 0.55);
  --q-lift: 0 1px 2px rgb(0 0 0 / 0.4);
  --q-float: 0 0 0 1px rgb(255 255 255 / 0.08), 0 18px 40px -12px rgb(0 0 0 / 0.7);
}
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gb.gb.gb.gb.gb[data-effect="flat"][data-variant="primary"] {
  background: linear-gradient(180deg, #ffffff, color-mix(in srgb, var(--glass-tint) 92%, #000) 60%);
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.5), inset 0 -1px 0 rgb(0 0 0 / 0.14), 0 0 0 1px rgb(0 0 0 / 0.5), 0 2px 6px -2px rgb(0 0 0 / 0.6);
}
[data-glass-mode="dark"] [data-glass-theme="quiet"]:not([data-glass-tint="ink"]) .gb.gb.gb.gb.gb[data-effect="flat"][data-variant="primary"] {
  background: linear-gradient(180deg, color-mix(in srgb, var(--glass-tint) 82%, #fff), var(--glass-tint) 55%);
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.2), 0 0 0 1px rgb(0 0 0 / 0.5), 0 2px 6px -2px rgb(0 0 0 / 0.6);
}
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gb.gb.gb.gb.gb[data-effect="flat"][data-variant="secondary"] { --gb-fg: var(--glass-fg); background: #1c1c1f; box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.05), 0 0 0 1px var(--q-line-strong); }
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gb.gb.gb.gb.gb[data-effect="flat"][data-variant="secondary"]:hover:not(:disabled) { background: #232327; }
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gf.gf:not([data-effect="glass"], [data-effect="bubble"]) { --gf-fill: #141416; --gf-ring: var(--q-line-strong); --gf-inset: inset 0 0 0 0 transparent; }
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gc.gc[data-effect="flat"] { --gc-fill: var(--q-surface); --gc-ring: var(--q-line); --gc-drop: 0 0 0 0 transparent; }
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gc.gc[data-effect="flat"][data-level="2"] { --gc-fill: #1a1a1d; }
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gtb.gtb { background: var(--q-surface); box-shadow: 0 0 0 1px var(--q-line); }
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gtb.gtb th { background: rgb(255 255 255 / 0.04); }
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gtb.gtb td { border-bottom-color: rgb(255 255 255 / 0.05); }
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gtabs.gtabs:not([data-variant="subtle"], [data-effect="glass"], [data-effect="bubble"]) .gtabs-pill { background: #2a2a2e; box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.06), 0 0 0 1px rgb(0 0 0 / 0.4); }
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gsb[data-effect="flat"] .gsb-item[aria-current="page"],
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gsb-count,
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gpg-btn[aria-current="page"] { color: var(--glass-fg); background: #1e1e21; box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.05), 0 0 0 1px var(--q-line-strong); }
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gsb-item { color: rgb(244 244 245 / 0.62); }
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gsb-label { color: rgb(244 244 245 / 0.4); }
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gbd[data-tone="accent"] { --gbd-c: #93b4ff; --gbd-bg: rgb(59 130 246 / 0.14); }
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gbd[data-tone="success"] { --gbd-c: #6ee7a0; --gbd-bg: rgb(34 197 94 / 0.12); }
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gbd[data-tone="warning"] { --gbd-c: #fcd34d; --gbd-bg: rgb(234 179 8 / 0.12); }
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gbd[data-tone="danger"] { --gbd-c: #fca5a5; --gbd-bg: rgb(239 68 68 / 0.13); }
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gch, [data-glass-mode="dark"] [data-glass-theme="quiet"] .gdn { --gch-1: #71717a; --gch-2: #3f3f46; --gch-3: #d4d4d8; }
[data-glass-mode="dark"] [data-glass-theme="quiet"] .gdl { background: #161618; }

/* ---------- Every other part follows the theme too ----------
   The newer families (extras, tactile, glance, kit and the AI parts) keep
   their own colour tokens. These rules route their surfaces, main buttons and
   quiet buttons through the theme. The doubled attribute lets them win over
   each family's own dark-mode rules. */
[data-glass-theme="quiet"] { --q-hair: rgb(var(--glass-shadow, 20 20 30) / 0.1); --q-lift: 0 1px 2px rgb(0 0 0 / 0.05); }
:is([data-glass-mode="dark"] [data-glass-theme="quiet"], [data-glass-mode="dark"][data-glass-theme="quiet"]) { --q-hair: rgb(255 255 255 / 0.1); --q-lift: 0 1px 2px rgb(0 0 0 / 0.4); }
/* family tokens: flat paper, no gloss, the colour used flat */
[data-glass-theme][data-glass-theme="quiet"] :is(.gx-confirm, .gx-cal, .gx-pop, .gx-hc, .gx-hold, .gx-swipe, .gx-pw, .gx-rate, .gx-undo, .gx-ts, .gx-bell, .gx-tick, .gx-fl, .gx-rs, .gx-ring, .gx-type, .gx-efield) { --x-surface: var(--x-top); --x-lit: 0 0 0 1px var(--q-hair), var(--q-lift); }
[data-glass-theme][data-glass-theme="quiet"] .gn.gn { --n-surf: var(--n-top); --n-lit: 0 0 0 1px var(--q-hair), var(--q-lift); --n-main: var(--n-c); --n-main-lit: none; }
[data-glass-theme][data-glass-theme="quiet"] :is(.ggl:not([data-fill]), .gxw, .gxs-item, .gxm-field, .gxm-list, .gxc-menu, .gxo-panel, .gxd, .gxa, .gcp, .gft, .gptr, .ghh, .gkc, .gst-item, .gam-err, .gam-hist, .gam-men, .gam-art, .gam-diff, .gam-vp-row, .gam-ap, .gdk-card, .gct-body, .gfb, .gap, .gis-pill, .gss) { box-shadow: 0 0 0 1px var(--q-hair), var(--q-lift); }
[data-glass-theme][data-glass-theme="quiet"] :is(.gx-btn-main, .gxb-main, .gxo-btn, .gxa-main, .gam-solid, .gam-men-send, .gam-ap-play, .gam-hist-new, .gkc-send:not([data-stop]), .gn-btn-main, .gn-send, .gn-aw-fab) { color: var(--glass-on-tint, #fff); background: var(--glass-tint); box-shadow: none; text-shadow: none; }
[data-glass-theme][data-glass-theme="quiet"] :is(.gx-btn:not(.gx-btn-main), .gxa-b:not(.gxa-main), .goa-b, .gam-ghost, .gap-btn, .gn-btn:not(.gn-btn-main), .gn-jump, .gn-chip-btn, .gn-ra-play, .gn-htt-btn, .gam-vp-play, .gct-btn, .gdk-btn, .gx-bell-btn, .grx-add, .gn-tools-btn) { background: transparent; box-shadow: inset 0 0 0 1px var(--q-hair); }
[data-glass-theme][data-glass-theme="quiet"] :is(.gx-btn:not(.gx-btn-main), .gxa-b:not(.gxa-main), .goa-b, .gam-ghost, .gap-btn, .gn-btn:not(.gn-btn-main), .gn-jump, .gn-chip-btn, .gn-ra-play, .gn-htt-btn, .gam-vp-play, .gct-btn, .gdk-btn, .gx-bell-btn, .grx-add, .gn-tools-btn):hover:not(:disabled) { background: rgb(var(--glass-shadow, 20 20 30) / 0.05); }
[data-glass-theme][data-glass-theme="quiet"] :is(.ggl, .gxw, .gcp, .gft, .gptr, .ghh, .gkc, .gam-hist, .gam-men, .gam-art, .gam-diff, .gam-ap, .gxd, .gxa, .gdk-card, .gap) { border-radius: 12px; }
